const crypto = require('crypto');

const WINDOW_SECONDS = 300;
const FUTURE_SKEW_SECONDS = 30;
const REPLAY_RETENTION_SECONDS = 7 * 24 * 60 * 60;
const MAX_REPLAY_RECORDS = 5000;

function response(statusCode, body) {
  return [{ json: { statusCode, body, headers: { 'Content-Type': 'application/json' } } }];
}

function getHeader(headers, name) {
  const target = name.toLowerCase();
  for (const [key, value] of Object.entries(headers || {})) {
    if (key.toLowerCase() === target) return Array.isArray(value) ? String(value[0] ?? '') : String(value ?? '');
  }
  return '';
}

function timingSafeSignatureEqual(expected, actual) {
  if (!/^sha256=[a-f0-9]{64}$/i.test(actual)) return false;
  const expectedHex = expected.slice('sha256='.length);
  const actualHex = actual.slice('sha256='.length);
  const expectedBuffer = Buffer.from(expectedHex, 'hex');
  const actualBuffer = Buffer.from(actualHex, 'hex');
  return expectedBuffer.length === actualBuffer.length && crypto.timingSafeEqual(expectedBuffer, actualBuffer);
}

function pruneReplayStore(store, nowSeconds) {
  const replay = store.replay || {};
  const entries = Object.entries(replay)
    .filter(([, value]) => nowSeconds - Number(value.seenAt || 0) <= REPLAY_RETENTION_SECONDS)
    .sort((a, b) => Number(b[1].seenAt || 0) - Number(a[1].seenAt || 0));
  store.replay = Object.fromEntries(entries.slice(0, MAX_REPLAY_RECORDS));
}

const vars = typeof $vars === 'undefined' ? {} : $vars;
const env = typeof $env === 'undefined' ? {} : $env;
const secret = String(vars.N8N_LEAD_AUTOMATION_SECRET || env.N8N_LEAD_AUTOMATION_SECRET || '').trim();
if (!secret) return response(500, { ok: false, error: 'receiver_not_configured' });

const item = $input.all()[0] || { json: {} };
const headers = item.json.headers || {};
const eventId = getHeader(headers, 'X-Lead-Event-Id').trim();
const timestamp = getHeader(headers, 'X-Lead-Timestamp').trim();
const signature = getHeader(headers, 'X-Lead-Signature').trim();
const rawBody = typeof item.json.rawBody === 'string' ? item.json.rawBody : '';

if (!eventId || eventId.length > 128 || !timestamp || !signature || !rawBody) {
  return response(400, { ok: false, error: 'invalid_request' });
}

if (!/^\d{10}$/.test(timestamp)) return response(400, { ok: false, error: 'invalid_timestamp' });
const nowSeconds = Math.floor(Date.now() / 1000);
const timestampSeconds = Number(timestamp);
if (nowSeconds - timestampSeconds > WINDOW_SECONDS) return response(401, { ok: false, error: 'timestamp_expired' });
if (timestampSeconds - nowSeconds > FUTURE_SKEW_SECONDS) return response(401, { ok: false, error: 'timestamp_in_future' });

const signingInput = `${timestamp}.${eventId}.${rawBody}`;
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(signingInput, 'utf8').digest('hex');
if (!timingSafeSignatureEqual(expected, signature)) return response(401, { ok: false, error: 'invalid_signature' });

const bodyHash = crypto.createHash('sha256').update(rawBody, 'utf8').digest('hex');
const store = $getWorkflowStaticData('global');
pruneReplayStore(store, nowSeconds);
store.replay = store.replay || {};
const previous = store.replay[eventId];
if (previous && previous.bodyHash === bodyHash) {
  return response(200, { ok: true, idempotent: true, event_id: eventId });
}
if (previous && previous.bodyHash !== bodyHash) {
  return response(409, { ok: false, error: 'event_replay_payload_mismatch' });
}

store.replay[eventId] = { bodyHash, seenAt: nowSeconds };
return response(200, { ok: true, idempotent: false, event_id: eventId });
